import { useMemo, useRef } from "react";
import { range } from "lodash";

import Checkbox from "@cloudscape-design/components/checkbox";
import ColumnLayout from "@cloudscape-design/components/column-layout";
import FormField from "@cloudscape-design/components/form-field";
import Input from "@cloudscape-design/components/input";

import CoreChart from "../../lib/components/internal-do-not-use/core-chart";
import { CoreChartProps } from "../../src/core/interfaces";
import { dateFormatter } from "../common/formatters";
import { PageSettings, PageSettingsForm, useChartSettings } from "../common/page-settings";
import { Page } from "../common/templates";
import pseudoRandom from "../utils/pseudo-random";

interface ThisPageSettings extends PageSettings {
  series?: number;
  charts?: number;
  instantSeries?: boolean;
  debounceDim?: boolean;
  debounceTooltip?: boolean;
}

const loremIpsum =
  "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Mauris congue aliquet feugiat. Integer gravida efficitur elementum. Interdum et malesuada fames ac ante ipsum primis in faucibus. Curabitur et nisi iaculis diam laoreet pharetra. Phasellus nec nibh dapibus, feugiat leo sodales, feugiat mi. Vivamus a orci mattis, fringilla nisl et, pretium metus. Nunc leo nisi, blandit et sodales ut, sodales id leo. Vestibulum consectetur ante et sapien pretium vestibulum. Donec cursus arcu vitae nunc convallis molestie. Nunc est elit, maximus eu odio eget, commodo fermentum felis. Nullam sit amet sem lectus. Quisque eu rhoncus libero, nec lacinia ipsum. Mauris libero nulla, placerat vitae nisi et, luctus placerat turpis. Donec vitae faucibus neque, eu accumsan enim. Cras nec arcu lacus. Aenean vehicula, mauris in vestibulum maximus, sem nisi rutrum mi, in lobortis lorem elit quis est.";

const domain = range(0, 33).map((i) => 1600984800000 + i * 900000);
const site1Data = [
  58020, 102402, 104920, 94031, 125021, 159219, 193082, 162592, 274021, 264286, 289210, 256362, 257306, 186776, 294020,
  385975, 486039, 490447, 361845, 339058, 298028, 231902, 224558, 253901, 102839, 234943, 204405, 190391, 183570,
  162592, 148910, 229492, 293910,
].map((v) => v * 0.9);
const site2Data = [
  151023, 169975, 176980, 168852, 149130, 147299, 169552, 163401, 154091, 199516, 195503, 189953, 181635, 192975,
  205951, 218958, 220516, 213557, 165899, 173557, 172331, 186492, 131541, 142262, 194091, 185899, 173401, 171635,
  179130, 185951, 144091, 152975, 157299,
].map((v) => v * 0.9);

function createSeriesData(count: number) {
  return range(0, count).map((index) => {
    const name =
      loremIpsum
        .slice(index * 20, (index + 1) * 20)
        .replace(/[\W]+/g, "-")
        .replace(/(^-)|(-$)/g, "")
        .toLowerCase() || `series-${index + 1}`;
    const data = index < 10 ? site1Data : site2Data;
    return {
      name,
      data: data.map((y, i) => ({ x: domain[i], y: y + Math.round((pseudoRandom() - 0.5) * (i + 1) * 5000) })),
    };
  });
}

function NumberSetting({
  label,
  value,
  onChange,
}: {
  label: string;
  value: number;
  onChange: (value: number) => void;
}) {
  return (
    <FormField label={label}>
      <Input
        type="number"
        value={String(value)}
        onChange={({ detail }) => onChange(detail.value ? parseInt(detail.value) : 1)}
      />
    </FormField>
  );
}

export default function () {
  const { settings, setSettings, chartProps } = useChartSettings<ThisPageSettings>();
  const seriesCount = Number(settings.series ?? 20);
  const chartCount = Number(settings.charts ?? 6);
  const legend = { ...chartProps.core.legend, bottomMaxHeight: Number(settings.legendBottomMaxHeight ?? 50) };
  const instantSeriesHighlight = String(settings.instantSeries) === "true";
  const debounceDimming = String(settings.debounceDim ?? "true") === "true";
  const debounceTooltip = String(settings.debounceTooltip ?? "true") === "true";
  const coreProps = {
    ...chartProps.core,
    legend,
    instantSeriesHighlight,
    debounceDimming,
    debounceTooltip,
  };
  const seriesData = useMemo(() => createSeriesData(seriesCount), [seriesCount]);
  const apis = useRef<(CoreChartProps.ChartAPI | null)[]>([]);

  const others = (index: number) => apis.current.filter((api, i) => i !== index && api) as CoreChartProps.ChartAPI[];
  const highlightSeriesInOthers = (index: number, seriesId: string) =>
    others(index).forEach((api) => api.highlightItems([seriesId]));
  const clearOthers = (index: number) => others(index).forEach((api) => api.clearChartHighlight());

  return (
    <Page
      title="Hover debounce, synced dashboard (local)"
      subtitle="Local test page, not part of the PR. Identical charts; only series highlights are synced between them. Set hoverDebounce, instantSeries, debounceDim, debounceTooltip, series and charts in the URL or page settings."
      settings={
        <PageSettingsForm
          selectedSettings={[
            "hoverDebounce",
            {
              content: (
                <Checkbox
                  checked={instantSeriesHighlight}
                  onChange={({ detail }) => setSettings({ instantSeries: detail.checked })}
                >
                  Instant series and legend highlight
                </Checkbox>
              ),
            },
            {
              content: (
                <Checkbox
                  checked={debounceDimming}
                  disabled={!instantSeriesHighlight}
                  onChange={({ detail }) => setSettings({ debounceDim: detail.checked })}
                >
                  Apply hoverDebounce to dim
                </Checkbox>
              ),
            },
            {
              content: (
                <Checkbox
                  checked={debounceTooltip}
                  disabled={!instantSeriesHighlight}
                  onChange={({ detail }) => setSettings({ debounceTooltip: detail.checked })}
                >
                  Apply hoverDebounce to tooltip
                </Checkbox>
              ),
            },
            {
              content: (
                <NumberSetting label="Series" value={seriesCount} onChange={(series) => setSettings({ series })} />
              ),
            },
            {
              content: (
                <NumberSetting label="Charts" value={chartCount} onChange={(charts) => setSettings({ charts })} />
              ),
            },
            "legendPosition",
            "legendBottomMaxHeight",
            "tooltipPlacement",
          ]}
        />
      }
    >
      <ColumnLayout columns={2}>
        {range(0, chartCount).map((index) => (
          <CoreChart
            key={`${index}-${seriesCount}`}
            {...coreProps}
            callback={(api) => (apis.current[index] = api)}
            chartHeight={250}
            ariaLabel={`Chart ${index + 1}`}
            options={{
              series: seriesData.map(({ name, data }) => ({
                id: name,
                name,
                type: "line" as const,
                data: data.map((d) => ({ ...d })),
              })),
              plotOptions: { series: { stacking: "normal" } },
              xAxis: [
                {
                  type: "datetime",
                  title: { text: "Time (UTC)" },
                  min: domain[0],
                  max: domain[domain.length - 1],
                  valueFormatter: dateFormatter,
                },
              ],
              yAxis: [{ title: { text: "Bytes transferred" } }],
            }}
            onHighlight={({ detail }) => {
              if (detail.isApiCall) {
                return;
              }
              if (detail.point) {
                highlightSeriesInOthers(index, detail.point.series.options.id ?? detail.point.series.name);
              } else {
                clearOthers(index);
              }
            }}
            onLegendItemHighlight={({ detail }) => highlightSeriesInOthers(index, detail.item.id)}
            onClearHighlight={({ detail }) => {
              if (!detail.isApiCall) {
                clearOthers(index);
              }
            }}
          />
        ))}
      </ColumnLayout>
    </Page>
  );
}
